import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Valores de prueba de tres armas","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/numeric-prototype.md","filePath":"es/guide/combat/numeric-prototype.md"}'),o={name:"es/guide/combat/numeric-prototype.md"};function i(n,t,s,c,l,m){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="three-weapon-test-numbers" tabindex="-1">Valores de prueba de tres armas <a class="header-anchor" href="#three-weapon-test-numbers" aria-label="Enlace permanente a &quot;Valores de prueba de tres armas&quot;">​</a></h1><p><strong>Estado:</strong> Experimental para los valores del prototipo · No implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Son valores de estado Experimental para Longsword, Spear y War Hammer, no equilibrio implementado.</li><li>Costes y fases se aplican a ambos modos; Modern elige cuándo empieza una acción disponible.</li><li>Consultá el perfil numérico completo para ventanas activas, modificadores y redondeo antes de calcular resultados.</li></ul><p>Son valores iniciales de prueba para futuras sesiones jugables, no equilibrio en vivo. Asumen Practiced, manejo neutral y ritmo Stable.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Arma</th><th>Identidad</th><th>Intervalo básico Legacy</th></tr></thead><tbody><tr><td>Longsword</td><td>Control cercano versátil</td><td>1300 ms</td></tr><tr><td>Spear</td><td>Gestión de distancia y castigo de aproximaciones</td><td>1550 ms</td></tr><tr><td>War Hammer</td><td>Impacto costoso y comprometido</td><td>2200 ms</td></tr></tbody></table><p>Los intervalos asumen stamina llena y DEX 50. Modern empieza cuando elegís una acción disponible; ambos modos deben terminar wind-up, fase activa y recuperación.</p><h2 id="longsword" tabindex="-1">Longsword <a class="header-anchor" href="#longsword" aria-label="Enlace permanente a &quot;Longsword&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SA / acción</th><th>Tipo</th><th>Alcance</th><th>Coste</th><th>Wind-up</th><th>Recuperación</th><th>Propósito</th></tr></thead><tbody><tr><td>Basic Slash</td><td>Básica</td><td>1</td><td>10</td><td>250 ms</td><td>600 ms</td><td>Corte fiable</td></tr><tr><td>Thrust</td><td>Ofensiva</td><td>1</td><td>13</td><td>300 ms</td><td>650 ms</td><td>Precisión estrecha</td></tr><tr><td>Feint</td><td>Engaño</td><td>1</td><td>7</td><td>250 ms</td><td>400 ms</td><td>Provocar defensa; sin daño</td></tr><tr><td>Riposte</td><td>Defensa</td><td>1</td><td>15</td><td>100 ms</td><td>650 ms</td><td>Responder a contacto compatible</td></tr></tbody></table><h2 id="spear" tabindex="-1">Spear <a class="header-anchor" href="#spear" aria-label="Enlace permanente a &quot;Spear&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SA / acción</th><th>Tipo</th><th>Alcance</th><th>Coste</th><th>Wind-up</th><th>Recuperación</th><th>Propósito</th></tr></thead><tbody><tr><td>Basic Thrust</td><td>Básica</td><td>2</td><td>12</td><td>350 ms</td><td>700 ms</td><td>Mantener distancia</td></tr><tr><td>Lunge</td><td>Ofensiva</td><td>3</td><td>22</td><td>500 ms</td><td>1000 ms</td><td>Extensión comprometida</td></tr><tr><td>Brace</td><td>Defensa</td><td>2</td><td>18</td><td>150 ms</td><td>850 ms</td><td>Responder al compromiso</td></tr><tr><td>Sweep</td><td>Ofensiva</td><td>1</td><td>20</td><td>450 ms</td><td>850 ms</td><td>Arco corto, hasta 2 hostiles</td></tr></tbody></table><h2 id="war-hammer" tabindex="-1">War Hammer <a class="header-anchor" href="#war-hammer" aria-label="Enlace permanente a &quot;War Hammer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SA / acción</th><th>Tipo</th><th>Alcance</th><th>Coste</th><th>Wind-up</th><th>Recuperación</th><th>Propósito</th></tr></thead><tbody><tr><td>Basic Swing</td><td>Básica</td><td>1</td><td>17</td><td>500 ms</td><td>1000 ms</td><td>Presión contundente</td></tr><tr><td>Heavy Blow</td><td>Ofensiva</td><td>1</td><td>28</td><td>750 ms</td><td>1400 ms</td><td>Castigar posición</td></tr><tr><td>Crushing Arc</td><td>Ofensiva</td><td>2</td><td>30</td><td>650 ms</td><td>1300 ms</td><td>Presión amplia, hasta 2 hostiles</td></tr><tr><td>Guard Break</td><td>Ofensiva</td><td>1</td><td>24</td><td>600 ms</td><td>1100 ms</td><td>Debilitar una postura activa</td></tr></tbody></table><p>Las tablas omiten duración activa para facilitar la lectura: consultar el perfil completo antes de calcular tiempo total de acción. La ventana activa base de Riposte es 450 ms; la de Brace, 1600 ms. Una activación exitosa termina la ventana defensiva restante e inicia recuperación.</p><h2 id="trade-offs" tabindex="-1">Ventajas y costes <a class="header-anchor" href="#trade-offs" aria-label="Enlace permanente a &quot;Ventajas y costes&quot;">​</a></h2><ul><li>Brace reduce un impacto compatible un 35%; Riposte un 25%, con un intento de respuesta elegible.</li><li>Guard Break reduce a la mitad esa reducción para su propio golpe y no activa respuesta de postura. No añade aturdimiento ni rotura permanente de armadura.</li><li>Finta, demora o flanqueo pueden desperdiciar una defensa. Sin contacto compatible no hay respuesta.</li><li>Ninguna acción concede alcance invisible, golpe extra gratuito ni daño de ráfaga ilimitado.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Modos</a> · <a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> · <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html">Perfil numérico completo</a></p>',19)])])}const u=a(o,[["render",i]]);export{p as __pageData,u as default};
